import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"41、【損】 兌下艮上","description":"橫渠易說 - 41、【損】 兌下艮上","frontmatter":{"title":"41、【損】 兌下艮上","description":"橫渠易說 - 41、【損】 兌下艮上"},"headers":[],"relativePath":"classics/hengqu/043.md","filePath":"classics/hengqu/043.md"}'),l={name:"classics/hengqu/043.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_41、【損】-兌下艮上" tabindex="-1">41、【損】 兌下艮上 <a class="header-anchor" href="#_41、【損】-兌下艮上" aria-label="Permalink to “41、【損】 兌下艮上”">​</a></h1><h3 id="彖曰-損-損下益上-其道上行。損而有孚元吉-無咎可貞-利有攸往。-曷之用-二簋可用享-二簋應有時-損剛益柔有時-損益盈虛-與時偕行。" tabindex="-1">彖曰：損，損下益上，其道上行。損而有孚元吉，無咎可貞，利有攸往。“曷之用？二簋可用享”，二簋應有時，損剛益柔有時，損益盈虛，與時偕行。 <a class="header-anchor" href="#彖曰-損-損下益上-其道上行。損而有孚元吉-無咎可貞-利有攸往。-曷之用-二簋可用享-二簋應有時-損剛益柔有時-損益盈虛-與時偕行。" aria-label="Permalink to “彖曰：損，損下益上，其道上行。損而有孚元吉，無咎可貞，利有攸往。“曷之用？二簋可用享”，二簋應有時，損剛益柔有時，損益盈虛，與時偕行。”">​</a></h3><h3 id="象曰-山下有澤-損-君子以懲忿窒欲。" tabindex="-1">象曰：山下有澤，損，君子以懲忿窒欲。 <a class="header-anchor" href="#象曰-山下有澤-損-君子以懲忿窒欲。" aria-label="Permalink to “象曰：山下有澤，損，君子以懲忿窒欲。”">​</a></h3><p>損下益上，損剛益柔，非可常行，必有孚元吉，無咎可貞，然後利有所進，故下雲“有時”。</p><h3 id="初九-已事遄往-無咎-酌損之。-象曰-已事遄往-尚合志也。" tabindex="-1">初九，已事遄往，無咎，酌損之。 象曰：“已事遄往”，尚合志也。 <a class="header-anchor" href="#初九-已事遄往-無咎-酌損之。-象曰-已事遄往-尚合志也。" aria-label="Permalink to “初九，已事遄往，無咎，酌損之。 象曰：“已事遄往”，尚合志也。”">​</a></h3><p>損剛益柔有時，損不可過，抑而居下，有為而然，故事已則當速反於上，與四合志。損不以中，未免於咎也。</p><h3 id="九二-利貞-徵兇-弗損益之。-象曰-九二利貞-中以為志也。" tabindex="-1">九二，利貞，徵兇，弗損益之。 象曰：“九二利貞”，中以為志也。 <a class="header-anchor" href="#九二-利貞-徵兇-弗損益之。-象曰-九二利貞-中以為志也。" aria-label="Permalink to “九二，利貞，徵兇，弗損益之。 象曰：“九二利貞”，中以為志也。”">​</a></h3><p>以陽居陰，剛德已損，故以徵則兇。能志於正，則雖損非損，其實受益。</p><h3 id="六三-三人行則損一人-一人行則得其友。-象曰-一人行-三則疑也。" tabindex="-1">六三，三人行則損一人，一人行則得其友。 象曰：一人行，三則疑也。 <a class="header-anchor" href="#六三-三人行則損一人-一人行則得其友。-象曰-一人行-三則疑也。" aria-label="Permalink to “六三，三人行則損一人，一人行則得其友。 象曰：一人行，三則疑也。”">​</a></h3><p>六三本為上六，與坤同體，若連茹匯徵，三人並行，則反非益上之道也。</p><h3 id="六四-損其疾-使遄有喜-無咎。-象曰-損其疾-亦可喜也。" tabindex="-1">六四，損其疾，使遄有喜，無咎。 象曰：“損其疾”，亦可喜也。 <a class="header-anchor" href="#六四-損其疾-使遄有喜-無咎。-象曰-損其疾-亦可喜也。" aria-label="Permalink to “六四，損其疾，使遄有喜，無咎。 象曰：“損其疾”，亦可喜也。”">​</a></h3><p>六三志應於上，近不相得，不固其路使速應於上，則初九之應無所間阻，故曰“損其疾”，使彼有喜，故己亦可喜而無咎也。</p><h3 id="六五-或益之十朋之龜-弗克違-元吉。-象曰-六五元吉-自上祐也。" tabindex="-1">六五，或益之十朋之龜，弗克違，元吉。 象曰：六五元吉，自上祐也。 <a class="header-anchor" href="#六五-或益之十朋之龜-弗克違-元吉。-象曰-六五元吉-自上祐也。" aria-label="Permalink to “六五，或益之十朋之龜，弗克違，元吉。 象曰：六五元吉，自上祐也。”">​</a></h3><p>龜弗能遠，言受益之可必，信然不疑也。“或益之”，上九自外來而比之，況其下者乎!</p><h3 id="上九-弗損益之-無咎-貞吉。利有攸往-得臣無家。-象曰-弗損益之-大得志也。" tabindex="-1">上九，弗損益之，無咎，貞吉。利有攸往，得臣無家。 象曰：“弗損益之”，大得志也。 <a class="header-anchor" href="#上九-弗損益之-無咎-貞吉。利有攸往-得臣無家。-象曰-弗損益之-大得志也。" aria-label="Permalink to “上九，弗損益之，無咎，貞吉。利有攸往，得臣無家。 象曰：“弗損益之”，大得志也。”">​</a></h3><p>上九本為九三，雖為損下，其實上行，故云“弗損益之”。損終反益，反如益卦損上而益下，則可大得志，至於得臣無家，(咎)［言］所有之多也。以剛在上，受下之益多矣，故(大川)［無所］施損，當反益於下，故曰“弗損益之”。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
